/*
 * A330976  Numbers that are not the number of factorizations into factors > 1
 *          of any positive integer.
 * https://oeis.org/A330976
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th natural number that is *not* equal to the
 *            number of multiplicative factorizations (into factors > 1) of
 *            any positive integer. The sequence is generated by scanning the
 *            values of the function f(k) = #factorizations(k) and recording
 *            the missing integers
 * Range:     u8 n <= 65, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   count_facts_uint64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include "../utils/count_facts_uint64.h"

/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/* Global data for the lazy precomputation.  The sequence is built on
   demand, but the first bulk computation is performed once. */
static bool          initialized  = false;
static uint64_t *    missing_vals  = NULL;   /* values are 64‑bit during build */
static size_t        missing_cnt   = 0;      /* number of values stored */
static size_t        missing_cap   = 0;      /* allocation capacity       */
static uint64_t      last_missing   = 0;      /* greatest value already stored */

/* ------------------------------------------------------------------ */
/* Bulk initialization:  compute f(k) for k up to a fixed bound,
   record which f-values have appeared, and then collect the missing
   integers up to the maximum observed f-value.  After this
   initialization any additional missing numbers are simply the
   consecutive integers beyond that maximum. */
static void init(void)
{
    if (initialized) return;

    /* Upper bound for k – chosen large enough to produce many missing
       terms (more than 10 000). */
    const uint64_t N = 200000;

    /* Dynamic array for marking which f-values have occurred.  The array
       grows as larger f-values are discovered. */
    size_t seen_cap = 4096;
    unsigned char *seen = (unsigned char *)calloc(seen_cap, 1);
    uint64_t max_f = 0;

    /* Compute f(k) for every k <= N. */
    for (uint64_t k = 2; k <= N; ++k) {
        uint64_t val = count_facts_uint64(k, 2);
        if (val > max_f) max_f = val;
        if (val >= seen_cap) {
            size_t new_cap = val + 1;
            seen = (unsigned char *)realloc(seen, new_cap);
            memset(seen + seen_cap, 0, new_cap - seen_cap);
            seen_cap = new_cap;
        }
        seen[val] = 1;
    }

    /* Allocate storage for missing sequence.  Start with a modest
       capacity and grow as needed. */
    missing_cap = 2048;
    missing_vals = (uint64_t *)malloc(missing_cap * sizeof(uint64_t));

    /* Collect all numbers <= max_f that have not appeared as f(k). */
    for (uint64_t cand = 1; cand <= max_f; ++cand) {
        if (!seen[cand]) {
            if (missing_cnt == missing_cap) {
                missing_cap <<= 1;
                missing_vals = (uint64_t *)realloc(missing_vals,
                                                  missing_cap * sizeof(uint64_t));
            }
            missing_vals[missing_cnt++] = cand;
        }
    }

    /* All integers > max_f are guaranteed missing.  The next value to
       be appended when more terms are required is max_f + 1. */
    last_missing = max_f;

    free(seen);
    initialized = true;
}

/* ------------------------------------------------------------------ */
/* Public function required by the assignment.  The function returns
   the n‑th term of A330976. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;      /* sequence is 1‑based; 0 is undefined */
    init();

    /* Grow the sequence lazily until we have at least n terms. */
    while (missing_cnt < n) {
        /* Append the next consecutive integer beyond the last stored
           value – these are all guaranteed to be missing. */
        ++last_missing;
        if (missing_cnt == missing_cap) {
            missing_cap <<= 1;
            missing_vals = (uint64_t *)realloc(missing_vals,
                                              missing_cap * sizeof(uint64_t));
        }
        missing_vals[missing_cnt++] = last_missing;
    }
    return (seq_t)missing_vals[n - 1];
}
